            .willReturn(List.of(createProduct("001", 4000)));

    List<Product> products =
            productRepository.findAllByProductNumberIn(List.of("001"));

    assertThat(products).hasSize(1);
}

TestDoubleTest > stub() PASSED

#   내가 정한 답이 나왔다

# --- 스텁 안 한 인자를 넣으면 ---

List<Product> products =
        productRepository.findAllByProductNumberIn(List.of("002"));

System.out.println(">>> " + products);

>>> []

#   002 는 스텁을 안 했다. 빈 목록이다

#   6.2절의 기본값이다

# --- 페이크 ---

public class FakeProductRepository implements ProductRepository {
    private final List<Product> store = new ArrayList<>();

    @Override
    public List<Product> saveAll(Iterable<Product> products) {
        products.forEach(store::add);
        return store;
    }

    @Override
    public List<Product> findAllByProductNumberIn(List<String> numbers) {
        return store.stream()
                .filter(p -> numbers.contains(p.getProductNumber()))
                .toList();
    }
    // ... JpaRepository 의 나머지 메서드는 UnsupportedOperationException
}

@Test
void fake() {
    FakeProductRepository fake = new FakeProductRepository();
    fake.saveAll(List.of(
            createProduct("001", 4000),
            createProduct("002", 4500)));

    List<Product> products = fake.findAllByProductNumberIn(List.of("001"));

    assertThat(products).hasSize(1)
            .extracting("productNumber").containsExactly("001");
}

TestDoubleTest > fake() PASSED

#   스텁을 안 했는데 002 를 걸러 냈다

#   진짜처럼 동작한다

# --- 페이크로 002 를 조회하면 ---

List<Product> products = fake.findAllByProductNumberIn(List.of("002"));

System.out.println(">>> " + products.size());

>>> 1

#   목이었으면 빈 목록이 나왔을 자리다

#   페이크는 넣은 데이터를 기억한다

# --- 인터페이스 메서드가 많으면 ---

$ ./gradlew compileTestJava

FakeProductRepository.java:12: error: FakeProductRepository is not abstract
  and does not override abstract method
  findAll(Sort) in ListPagingAndSortingRepository

#   JpaRepository 를 구현하면 다 채워야 한다

$ grep -c "@Override" FakeProductRepository.java
23

#   23개다. 그중 두 개만 쓴다

#   나머지는 UnsupportedOperationException 이다

#   그래서 이 책은 리포지토리를 페이크로 안 만든다

# --- 스텁과 목이 같은 객체인 것 ---

@Test
void stubAndMock() {
    // 스텁으로 쓴다
    given(mailSendClient.sendEmail(any(), any(), any(), any()))
            .willReturn(true);

    boolean result = mailService.sendMail("", "", "", "");

    assertThat(result).isTrue();

    // 같은 객체를 목으로 쓴다
    verify(mailSendClient).sendEmail(any(), any(), any(), any());
}

TestDoubleTest > stubAndMock() PASSED

#   객체는 하나다

#   쓰는 방식이 이름을 정한다

# --- 다섯을 한 표로 ---

#            불리나   답을 주나   기록하나   단언 대상
#   dummy    아니오    -          -          -
#   fake     예       진짜로      -          결과
#   stub     예       정해진 답    -          결과
#   spy      예       진짜로      예         결과 또는 호출
#   mock     예       정해진 답    예         호출

#   fake 와 stub 의 차이는 '어디서 답이 오나' 다

